}

package riscvdemo

import "gno.land/p/nym-moultest123/x/vm/riscv/v0"

// The programs the front page offers, as the machine words a cross compiler
// would have emitted. They are assembled outside this repo and pinned here,
// and riscvdemo_test.gno runs every one of them to the expected answer, so a
// wrong word is a failing test rather than a page that traps when clicked.
type sample struct {
	slug   string // what UploadSample takes: short, no punctuation, stable
	name   string
	budget int64 // the instance's total instruction budget, not the slice

	// builtin names an image the library ships compiled, instead of the words
	// below. Empty means the words are the program.
	builtin string
	words []uint32
	input string
	note  string
	asm   string
}

var samples = []sample{
	{
		slug: "hello",
		name: "Hello, gno.land",
		words: []uint32{
			0x00100513, 0x000015B7, 0x02058593, 0x01000613,
			0x04000893, 0x00000073, 0x05D00893, 0x00000073,
			0x6C6C6548, 0x67202C6F, 0x6C2E6F6E, 0x0A646E61,
		},
		budget: 1000,
		note: "Eight instructions and a string constant. The write syscall reads " +
			"the bytes straight out of the text segment and hands them to Host.Output.",
		asm: `addi a0, zero, 1          # fd
lui  a1, 0x1000           # buf
addi a1, a1, 0x20
addi a2, zero, 16         # len
addi a7, zero, 64         # write
ecall
addi a7, zero, 93         # exit
ecall
.ascii "Hello, gno.land\n"`,
	},
	{
		slug: "sum100",
		name: "Sum 1 to 100",
		words: []uint32{
			0x06400413, 0x00000293, 0x00000313, 0x00130313,
			0x006282B3, 0xFE831CE3, 0x05D00893, 0x00000073,
		},
		budget: 1000,
		note: "A real loop, 303 instructions. Writes nothing: the answer is in t0, " +
			"and the instance page shows the register file.",
		asm: `addi s0, zero, 100
addi t0, zero, 0
addi t1, zero, 0
loop:
addi t1, t1, 1
add  t0, t0, t1
bne  t1, s0, loop
addi a7, zero, 93
ecall`,
	},
	{
		slug: "heavy",
		name: "Heavy loop",
		words: []uint32{
			0x0000C437, 0x35040413, 0x00000293, 0x00000313,
			0x00130313, 0x006282B3, 0x00000393, 0xFE831AE3,
			0x05D00893, 0x00000073,
		},
		budget: 250000,
		note: "200,006 instructions, four per iteration. At the largest slice this realm " +
			"allows it takes three transactions to finish, which is the thing it exists to show.",
		asm: `lui  s0, 0xc000           # s0 = 50000
addi s0, s0, 0x350
addi t0, zero, 0
addi t1, zero, 0
loop:
addi t1, t1, 1
add  t0, t0, t1
addi t2, zero, 0
bne  t1, s0, loop
addi a7, zero, 93
ecall`,
	},
	{
		slug: "mext",
		name: "Multiply and divide",
		words: []uint32{
			0x3B9AD2B7, 0xA0728293, 0x00300313, 0x026282B3,
			0x00700393, 0x0272D333, 0x05D00893, 0x00000073,
		},
		budget: 1000,
		note: "The M extension. t0 = 1000000007 * 3 truncated to 32 bits, then t1 = t0 / 7. " +
			"Division by zero and the one signed overflow case return values here " +
			"rather than trapping, which is what the spec says and what a chain needs.",
		asm: `lui  t0, 0x3b9ad000       # t0 = 1000000007
addi t0, t0, -1529
addi t1, zero, 3
mul  t0, t0, t1
addi t2, zero, 7
divu t1, t0, t2
addi a7, zero, 93
ecall`,
	},
	{
		slug:   "clang",
		name:   "Compiled by clang",
		input:  "gno.land",
		budget: 20000,
		note: "Not written for gno and not written by hand: a freestanding C program, " +
			"compiled by clang for riscv32im and shipped as the bytes LLVM emitted. It reads " +
			"the call input, hashes it with FNV-1a and writes eight hex digits back. " +
			"With the default input it prints fb7ffba0. Source and build command: " +
			"tools/riscv-guests/fnv.",
		builtin: "fnv",
		asm: `long n = syscall3(SYS_READ, 0, (long)in, sizeof(in));

unsigned int h = 2166136261u;
for (long i = 0; i < n; i++) {
	h ^= in[i];
	h *= 16777619u;      /* the reason this is rv32im */
}

for (int i = 0; i < 8; i++) {
	unsigned int nib = (h >> (28 - i * 4)) & 0xF;
	out[i] = nib < 10 ? '0' + nib : 'a' + (nib - 10);
}

syscall3(SYS_WRITE, 1, (long)out, 8);
syscall3(SYS_EXIT, 0, 0, 0);`,
	},
	{
		slug:   "ledger",
		name:   "A token, in Rust",
		input:  "mint alice 100\nmint bob 50\nsend alice bob 30\n",
		budget: 20000,
		note: "no_std Rust, compiled by rustc for riscv32im: mint, send and burn, applied " +
			"from the call input. It links Rust's real core and compiler_builtins, so the " +
			"balances being 64-bit means a divide runs __udivdi3 here, because RV32 has no " +
			"64-bit divide instruction. With the default input it prints alice 70 and bob 80. " +
			"Source: tools/riscv-guests/ledger.",
		builtin: "ledger",
		asm: `match cmd {
	b"send" => {
		let (from, rest) = field(rest);
		let (to, rest) = field(rest);
		let (amount, _) = field(rest);
		let n = parse_u32(amount).ok_or("bad amount")?;
		let fi = led.find(from).ok_or("unknown sender")?;
		if led.balances[fi] < n {
			return Err("insufficient balance");
		}
		let ti = led.intern(to).ok_or("ledger full or bad name")?;
		led.balances[fi] -= n;
		led.balances[ti] += n;
		Ok(())
	}
	_ => Err("unknown command"),
}`,
	},
}

// image is what gets uploaded: either the words assembled here, or a program
// the library ships because a compiler produced it.
func (s *sample) image() []byte {
	switch s.builtin {
	case "fnv":
		return riscv.GuestFNV()
	case "ledger":
		return riscv.GuestLedger()
	}
	return riscv.Image(s.words)
}

// lang is the fence tag for what the sample shows. The compiled guest shows
// its C, because showing a disassembly of what LLVM did with it would bury the
// only interesting fact: nobody wrote the machine code.
func (s *sample) lang() string {
	switch s.builtin {
	case "fnv":
		return "c"
	case "ledger":
		return "rust"
	}
	return "asm"
}

func sampleByName(slug string) *sample {
	for i := range samples {
		if samples[i].slug == slug {
			return &samples[i]
		}
	}
	return nil
}

// GnoMoji — Main Game Realm
// gno.land/r/gnomoji/game
//
// On-chain game engine for GnoMoji on Gno.land (v1.5.0 / Onyx testnet API).
// Tracks mined coins, casino rounds, PvP lobbies, tools, skills, achievements.
//
// Token minting is handled by gno.land/r/gnomoji/minter (the treasury realm).
// GRC20 coin realms live at gno.land/r/gnomoji/coins/{coinId}.

package game2

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// ── State ────────────────────────────────────────────────────────────────────

var (
	admin          address
	pendingMints   avl.Tree // addr+":"+coinId → amount string
	balances       avl.Tree // addr+":"+coinId → amount string
	veinSupply     avl.Tree // coinId → "remaining:max"
	casinoRounds   avl.Tree // roundId → JSON string
	pvpLobbies     avl.Tree // lobbyId → JSON string
	ownedTools     avl.Tree // addr → comma-separated tool IDs
	toolLife       avl.Tree // addr+":"+toolId → remaining life string
	lifetimeMined  avl.Tree // addr+":"+coinId → total mined string
	achievements   avl.Tree // addr+":"+achId → "1"
	dailyCheckins  avl.Tree // addr → unix seconds string
	skillRanks     avl.Tree // addr+":"+skillId → rank string
	miners         avl.Tree // addr → total mined all-time string
	paused         bool
)

func init(cur realm) {
	admin = cur.Previous().Address()
}

// ── Admin ────────────────────────────────────────────────────────────────────

func isAdmin(cur realm) bool {
	return cur.Previous().Address() == admin
}

func UpdateConfig(cur realm, newAdmin string) {
	if !isAdmin(cur) {
		panic("unauthorized")
	}
	admin = address(newAdmin)
}

func SetPaused(cur realm, p bool) {
	if !isAdmin(cur) {
		panic("unauthorized")
	}
	paused = p
}

func requireNotPaused() {
	if paused {
		panic("game is paused")
	}
}

// ── Mining ───────────────────────────────────────────────────────────────────

// ClaimMine records mined coins into pending mints for the caller.
// coinsJson format: [["coinId","amount"],...]
func ClaimMine(cur realm, coinsJson string) {
	requireNotPaused()
	caller := cur.Previous().Address().String()

	coinsJson = strings.TrimSpace(coinsJson)
	coinsJson = strings.TrimPrefix(coinsJson, "[")
	coinsJson = strings.TrimSuffix(coinsJson, "]")

	for _, entry := range splitJsonArray(coinsJson) {
		entry = strings.TrimSpace(entry)
		entry = strings.TrimPrefix(entry, "[")
		entry = strings.TrimSuffix(entry, "]")
		parts := strings.SplitN(entry, ",", 2)
		if len(parts) != 2 {
			continue
		}
		coinId := strings.Trim(strings.TrimSpace(parts[0]), `"`)
		amtStr := strings.Trim(strings.TrimSpace(parts[1]), `"`)
		amt, err := strconv.ParseUint(amtStr, 10, 64)
		if err != nil || amt == 0 {
			continue
		}

		// Cap at vein supply if registered
		if veinSupply.Has(coinId) {
			vsStr := veinSupply.Get(coinId).(string)
			p2 := strings.SplitN(vsStr, ":", 2)
			if len(p2) == 2 {
				rem, _ := strconv.ParseUint(p2[0], 10, 64)
				if rem == 0 {
					continue
				}
				if amt > rem {
					amt = rem
				}
				maxV, _ := strconv.ParseUint(p2[1], 10, 64)
				veinSupply.Set(coinId, ufmt.Sprintf("%d:%d", rem-amt, maxV))
			}
		}

		key := caller + ":" + coinId

		// Accumulate pending mints
		ex := uint64(0)
		if pendingMints.Has(key) {
			ex, _ = strconv.ParseUint(pendingMints.Get(key).(string), 10, 64)
		}
		pendingMints.Set(key, strconv.FormatUint(ex+amt, 10))

		// Track lifetime mined per coin
		lifEx := uint64(0)
		if lifetimeMined.Has(key) {
			lifEx, _ = strconv.ParseUint(lifetimeMined.Get(key).(string), 10, 64)
		}
		lifetimeMined.Set(key, strconv.FormatUint(lifEx+amt, 10))

		// Update leaderboard total (all coins summed)
		mt := uint64(0)
		if miners.Has(caller) {
			mt, _ = strconv.ParseUint(miners.Get(caller).(string), 10, 64)
		}
		miners.Set(caller, strconv.FormatUint(mt+amt, 10))
	}
}

// ClearPendingMints is called by the minter realm after successful GRC20 minting.
func ClearPendingMints(cur realm, playerAddr string, coinsJson string) {
	if !isAdmin(cur) {
		panic("unauthorized: only admin/minter can clear pending mints")
	}
	coinsJson = strings.TrimSpace(coinsJson)
	coinsJson = strings.TrimPrefix(coinsJson, "[")
	coinsJson = strings.TrimSuffix(coinsJson, "]")
	for _, entry := range splitJsonArray(coinsJson) {
		coinId := strings.Trim(strings.TrimSpace(entry), `"`)
		if coinId != "" {
			pendingMints.Remove(playerAddr + ":" + coinId)
		}
	}
}

// ── Casino ───────────────────────────────────────────────────────────────────

func CommitCasinoSeed(cur realm, roundId string, seedHash string) {
	if !isAdmin(cur) {
		panic("unauthorized")
	}
	casinoRounds.Set(roundId, `{"roundId":"`+roundId+`","seedHash":"`+seedHash+`","status":"committed","bets":[]}`)
}

func PlaceCasinoBet(cur realm, roundId string, game string, coinId string, betAmount string, choice string, clientSeed string) {
	requireNotPaused()
	caller := cur.Previous().Address().String()
	amt, err := strconv.ParseUint(betAmount, 10, 64)
	if err != nil || amt == 0 {
		panic("invalid bet amount")
	}

	balKey := caller + ":" + coinId
	existing := uint64(0)
	if balances.Has(balKey) {
		existing, _ = strconv.ParseUint(balances.Get(balKey).(string), 10, 64)
	}
	if existing < amt {
		panic("insufficient balance")
	}
	balances.Set(balKey, strconv.FormatUint(existing-amt, 10))

	if !casinoRounds.Has(roundId) {
		panic("round not found")
	}
	bet := `{"addr":"` + caller + `","game":"` + game + `","coinId":"` + coinId + `","amount":` + betAmount + `,"choice":"` + choice + `","clientSeed":"` + clientSeed + `"}`
	casinoRounds.Set(roundId+":bet:"+caller, bet)
}

func RevealCasinoSeed(cur realm, roundId string, serverSeed string) {
	if !isAdmin(cur) {
		panic("unauthorized")
	}
	casinoRounds.Set(roundId+":serverSeed", serverSeed)
	casinoRounds.Set(roundId+":status", "revealed")
}

func RefundCasinoBet(cur realm, roundId string) {
	requireNotPaused()
	caller := cur.Previous().Address().String()
	betKey := roundId + ":bet:" + caller
	if !casinoRounds.Has(betKey) {
		panic("no bet found for this round")
	}
	casinoRounds.Remove(betKey)
}

// ── PvP Lobbies ──────────────────────────────────────────────────────────────

func CreatePvpLobby(cur realm, game string, coinId string, betAmount string) string {
	requireNotPaused()
	caller := cur.Previous().Address().String()
	prefix := caller
	if len(prefix) > 8 {
		prefix = caller[:8]
	}
	lobbyId := ufmt.Sprintf("pvp-%s-%d", prefix, time.Now().Unix())
	lobby := `{"lobbyId":"` + lobbyId + `","creator":"` + caller + `","game":"` + game + `","coinId":"` + coinId + `","betAmount":` + betAmount + `,"status":"open","round":1,"createdAt":` + strconv.FormatInt(time.Now().Unix(), 10) + `}`
	pvpLobbies.Set(lobbyId, lobby)
	return lobbyId
}

